function calc(s){const fail=m=>{throw Error(m)};if(s.runs.length!==s.total||new Set(s.runs.map(r=>r.id)).size!==s.total)fail("run inventory");const skips=s.runs.filter(r=>r.status==="completed"&&r.conclusion==="skipped"&&r.event==="pull_request"&&["ci","reproducibility"].includes(r.name));if(s.jobReceipts.length!==skips.length||new Set(s.jobReceipts.map(j=>j.run)).size!==skips.length)fail("receipt inventory");let placeholders=0,groups={};for(const r of skips){const j=s.jobReceipts.find(j=>j.run===r.id);if(!j||j.jobs.length!==j.total||j.total>50||new Set(j.jobs.map(j=>j.id)).size!==j.total||r.attempt!==1)fail("job inventory");if(!j.jobs.every(x=>x.head===r.head&&x.attempt===r.attempt&&x.status==="completed"&&x.conclusion==="skipped"&&!x.runner&&x.steps===0))fail("nonzero or foreign execution");placeholders+=j.total;const key=r.branch+"|"+r.head;const g=groups[key]??={branch:r.branch,head:r.head,ci:0,reproducibility:0,pr:r.pr.map(p=>p.number)};g[r.name]++}return {allRuns:s.total,zeroAllocationRuns:skips.length,placeholders,uniqueBranchHeads:Object.keys(groups).length,pairedBranchHeads:Object.values(groups).filter(g=>g.ci&&g.reproducibility).length,groups:Object.values(groups),otherRuns:s.runs.filter(r=>!skips.some(x=>x.id===r.id)).map(r=>({id:r.id,status:r.status,conclusion:r.conclusion,name:r.name,event:r.event,head:r.head}))}}
function test(s,cases){return cases.map(([name,mut])=>{const x=JSON.parse(JSON.stringify(s));mut(x);try{calc(x)}catch(e){return {name,refused:e.message}}throw Error("accepted "+name)})}
const cases=[["missing run",s=>s.runs.pop()],["duplicate receipt",s=>s.jobReceipts[1]=s.jobReceipts[0]],["runner assigned",s=>s.jobReceipts[0].jobs[0].runner="runner"],["foreign head",s=>s.jobReceipts[0].jobs[0].head="0".repeat(40)],["executed step",s=>s.jobReceipts[0].jobs[0].steps=1],["missing job",s=>s.jobReceipts[0].jobs.pop()],["changed attempt",s=>s.jobReceipts[0].jobs[0].attempt=2]];
console.log(JSON.stringify({metrics:calc(receipt),tests:test(receipt,cases),authority:false},null,2));
